-- State transitions declared for SAMLProvider (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.saml_providers_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'inactive'), ('draft', 'active'), ('inactive', 'active'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: saml_providers.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS saml_providers_status_transition_check ON sapiens.saml_providers;
CREATE TRIGGER saml_providers_status_transition_check
    BEFORE UPDATE OF "status" ON sapiens.saml_providers
    FOR EACH ROW EXECUTE FUNCTION sapiens.saml_providers_status_transition_check();
